import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { getPendingUsers, approveUser, rejectUser } from '../api';

export default function Admin() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const response = await getPendingUsers();
      setUsers(response.data.users);
    } catch (err) {
      setError('Failed to fetch users');
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (email) => {
    try {
      await approveUser({ email });
      setUsers(users.filter(user => user.email !== email));
    } catch (err) {
      setError('Failed to approve user');
    }
  };

  const handleReject = async (email) => {
    try {
      await rejectUser({ email });
      setUsers(users.filter(user => user.email !== email));
    } catch (err) {
      setError('Failed to reject user');
    }
  };

  if (loading) return <div className="text-center mt-16">Loading...</div>;

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-4xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">Admin Panel - Pending Users</h1>
      {error && <p className="text-red-400 mb-4">{error}</p>}
      {users.length === 0 ? (
        <p className="text-slate-300">No pending users.</p>
      ) : (
        <div className="space-y-4">
          {users.map(user => (
            <div key={user.id} className="flex justify-between items-center bg-slate-700 p-4 rounded-lg">
              <span>{user.email}</span>
              <div className="space-x-2">
                <button onClick={() => handleApprove(user.email)} className="px-4 py-2 bg-green-600 hover:bg-green-500 rounded-lg font-semibold transition">
                  Approve
                </button>
                <button onClick={() => handleReject(user.email)} className="px-4 py-2 bg-red-600 hover:bg-red-500 rounded-lg font-semibold transition">
                  Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </motion.div>
  );
}
